head.script:
scwin.onpageload = function () {
    let arr = [
        { "item" : "노트북", "orderDate" : "20261028" },
        { "item" : "모니터", "orderDate" : "20251231" }
    ];
    dlt_a.setJSON(arr);
    dlt_b.setJSON(arr);
    dlt_c.setJSON(arr);
};

// advancedExcelDownload 실행 + 서버로 전송된 orderDate Column 정보 출력
scwin.download = function (grd, name) {
    let sBody = "";
    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        let objInput = this.querySelector("input[name=xmlValue]");
        if (sBody === "" && objInput) {
            sBody = objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };
    try {
        grd.advancedExcelDownload({ "fileName" : "grid_" + name, "extension" : "xlsx", "useDataFormat" : "true" });
    } finally {
        HTMLFormElement.prototype.submit = fnSubmit;
    }
    scwin.setReturnValue("[" + name + "] 전송 orderDate Column : " + scwin.getSentColumn(sBody, "orderDate") + " / 값 : " + scwin.getSentData(sBody, 1));
};

// 전송 XML 의 Body 영역에서 Column 의 dataType, displayFormat 을 읽는다
scwin.getSentColumn = function (sBody, sColId) {
    let nStart = sBody.indexOf("<w2:gBody");
    let sBodyXml = (nStart < 0) ? "" : sBody.substring(nStart, sBody.indexOf("</w2:gBody>", nStart));
    let arrTag = sBodyXml.split("<w2:column");
    for (let i = 1; i < arrTag.length; i++) {
        let sTag = arrTag[i].substring(0, arrTag[i].indexOf(">"));
        if (sTag.indexOf(' id="' + sColId + '"') < 0) {
            continue;
        }
        let objType = sTag.match(/ dataType="([^"]*)"/);
        let objFormat = sTag.match(/ displayFormat="([^"]*)"/);
        return "dataType=" + (objType ? objType[1] : "(없음)") + ", displayFormat=" + (objFormat && objFormat[1] !== "" ? objFormat[1] : "(없음)");
    }
    return "(미전달)";
};

// 전송 XML 의 data 배열에서 지정 Column 인덱스의 값만 모은다
scwin.getSentData = function (sBody, nColIndex) {
    let objMatch = sBody.match(/hashkey='data'><array><!\[CDATA\[(.*?)\]\]><\/array>/);
    if (objMatch === null) {
        return "(미전달)";
    }
    let arrData = JSON.parse(objMatch[1]);
    let arrValue = [];
    for (let i = nColIndex; i < arrData.length; i += 2) {
        arrValue.push(arrData[i]);
    }
    return arrValue.join(", ");
};

scwin.btn_a_onclick = function () { scwin.download(grd_a, "A"); };
scwin.btn_b_onclick = function () { scwin.download(grd_b, "B"); };
scwin.btn_c_onclick = function () { scwin.download(grd_c, "C"); };

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
